extern alias apiv2;using System.Net;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;using Xunit;using V2Program=apiv2::Program;
namespace SanSo.Api.V2.Tests;
public class ApiV2CompositionTests
{
 [Fact]public async Task DevelopmentWithoutDatabaseIsExplicitlyDegradedButDemoReadsWork(){await using var factory=new WebApplicationFactory<V2Program>().WithWebHostBuilder(x=>x.UseEnvironment("Development").UseSetting("ConnectionStrings:Postgres",string.Empty));using var client=factory.CreateClient();var health=await client.GetStringAsync("/health");Assert.Contains("database\":\"not-configured",health);using var request=new HttpRequestMessage(HttpMethod.Get,"/api/dashboard");request.Headers.Add("X-Tenant-Id","tenant-an-nhien");var dashboard=await client.SendAsync(request);Assert.Equal(HttpStatusCode.OK,dashboard.StatusCode);}
 [Fact]public async Task ProductionRequiresBearerBeforeDatabaseQuery(){await using var factory=new WebApplicationFactory<V2Program>().WithWebHostBuilder(x=>{x.UseEnvironment("Production");x.UseSetting("ConnectionStrings:Postgres","Host=127.0.0.1;Port=1;Database=sanso;Username=x;Password=x;Timeout=1");});using var client=factory.CreateClient();using var request=new HttpRequestMessage(HttpMethod.Get,"/api/dashboard");request.Headers.Add("X-Tenant-Id","11111111-1111-1111-1111-111111111111");var response=await client.SendAsync(request);Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);}
 [Fact]public async Task DevelopmentRawWriteRefusesSilentInMemoryFallback(){await using var factory=new WebApplicationFactory<V2Program>().WithWebHostBuilder(x=>x.UseEnvironment("Development").UseSetting("ConnectionStrings:Postgres",string.Empty));using var client=factory.CreateClient();using var request=new HttpRequestMessage(HttpMethod.Post,"/api/raw-events"){Content=JsonContent.Create(new{source="csv",eventId="e1",eventType="ORDER",payload="{}",schemaVersion="1"})};request.Headers.Add("X-Tenant-Id","tenant-an-nhien");var response=await client.SendAsync(request);Assert.Equal(HttpStatusCode.ServiceUnavailable,response.StatusCode);}
}
